type shunt struct{ seen []string }              // the test object

func (s *shunt) OnEvent(e string) { s.seen = append(s.seen, e) }

func TestPublishesOnce(t *testing.T) {
	s := &shunt{}
	p := NewPublisher(s)                        // install the test-local object
	p.Change("x")
	if !reflect.DeepEqual(s.seen, []string{"x"}) {
		t.Fatalf("seen = %v, want [x]", s.seen)
	}
}
